<template>
	<Dialog :open="open" @update:open="(value: boolean) => !value && $emit('close')"><DialogContent class="max-w-3xl max-h-[85vh] overflow-y-auto"><DialogHeader><DialogTitle class="flex items-center gap-2"><Monitor class="h-5 w-5" /> Customer Display</DialogTitle><DialogDescription>Show the live cart on a customer-facing second monitor.</DialogDescription></DialogHeader>
		<div class="flex items-center justify-between gap-3 border-b border-border pb-3"><div class="flex gap-2"><Button size="sm" :variant="tab === 'quick' ? 'default' : 'outline'" @click="tab = 'quick'">Quick Controls</Button><Button size="sm" :variant="tab === 'content' ? 'default' : 'outline'" @click="tab = 'content'">Content</Button><Button size="sm" :variant="tab === 'settings' ? 'default' : 'outline'" @click="tab = 'settings'">Settings</Button></div><Button size="sm" @click="openCustomerDisplay">Open Customer Display</Button></div>
		<div v-if="tab === 'quick'" class="space-y-5 text-sm">
			<div class="rounded-lg border border-border p-3 space-y-3"><div class="flex items-center justify-between gap-4"><div><p class="font-medium">Live Customer Screen</p><p class="text-xs text-muted-foreground">Show the live cart and payment updates on the customer screen. This data stays in this browser only.</p></div><Checkbox v-model:checked="enabled" /></div><div class="border-t border-border pt-3"><p class="font-medium" :class="connectionClass"><span class="mr-2">●</span>{{ connectionLabel }}</p><p class="mt-1 text-xs text-muted-foreground">{{ connectionHelp }}</p><p class="mt-1 text-xs text-muted-foreground">{{ storageLabel }}</p></div></div>
			<div class="rounded-lg border border-border p-4 space-y-4"><div><p class="font-medium">Saved Display Setup</p><p class="text-xs text-muted-foreground">A setup keeps the related Customer Display settings, company logo and complete Content playlist together.</p></div><div class="space-y-2"><label class="font-medium" for="saved-display-setup">Current setup</label><div class="flex gap-2"><select id="saved-display-setup" v-model="selectedSetup" class="select flex-1" @change="restoreSelectedSetup"><option value="">Select a saved setup…</option><option v-for="setup in savedSetups" :key="setup.terminal_id" :value="setup.terminal_id">{{ displaySetupName(setup.terminal_id) }}</option></select><Button variant="outline" size="sm" @click="refreshSavedSetups">Refresh</Button></div></div><div v-if="selectedSetup" class="rounded-md bg-muted p-3"><div class="flex flex-wrap items-center justify-between gap-3"><div><p class="font-medium">Editing: {{ displaySetupName(selectedSetup) }}</p><p class="text-xs text-muted-foreground">Save the changes made in this dialog to this selected setup.</p></div><div class="flex gap-2"><Button size="sm" @click="updateSelectedSetup">Save Changes</Button><Button variant="destructive" size="sm" @click="deleteSelectedSetup">Delete Setup</Button></div></div><details class="mt-3 text-xs text-muted-foreground"><summary class="cursor-pointer font-medium">Advanced: pairing link</summary><div class="mt-2 flex gap-2"><code class="min-w-0 flex-1 truncate rounded-md border border-input bg-background px-3 py-2 text-sm">{{ pairingUrl }}</code><Button variant="outline" size="sm" @click="copyPairingUrl">Copy Link</Button></div><p class="mt-1">Use this full link only when pairing manually. The button at the top opens the customer screen automatically.</p></details></div><div class="border-t border-border pt-4 space-y-2"><div><p class="font-medium">Create another setup</p><p class="text-xs text-muted-foreground">Use a clear name for each counter, for example Front Counter or Cashier 2.</p></div><div class="flex gap-2"><Input v-model="setupName" placeholder="New setup name" /><Button size="sm" @click="saveAsSetup">Save as New</Button></div></div></div>
		</div>
		<div v-else-if="tab === 'settings'" class="space-y-5 text-sm">
			<div class="rounded-lg border border-border p-3 space-y-2"><label class="font-medium">Company logo</label><div class="flex flex-wrap items-center gap-3"><img v-if="companyLogo" :src="companyLogo" class="logo-preview" alt="Company logo preview" /><input id="customer-display-logo" class="sr-only" type="file" accept="image/*" @change="uploadLogo" /><label for="customer-display-logo" class="file-button">Upload logo</label><Button v-if="companyLogo" size="sm" variant="outline" @click="companyLogo = ''">Remove</Button></div><p v-if="companyLogo" class="text-xs" :class="logoStatusClass">{{ fileName(companyLogo) }} · {{ logoStatus }}</p><p class="text-xs text-muted-foreground">Shown at a small, fixed size on the customer display.</p></div>
			<div class="rounded-lg border border-border p-3 space-y-3"><p class="font-medium">Customer journey</p><label class="flex items-center gap-2"><Checkbox v-model:checked="activeMedia" /> Show advertisement beside receipt during checkout</label><div class="space-y-2 pl-6"><div class="flex items-center justify-between"><label class="font-medium" for="customer-display-receipt-width">Receipt width</label><span class="text-xs text-muted-foreground">{{ receiptWidth }}% receipt / {{ 100 - receiptWidth }}% content</span></div><input id="customer-display-receipt-width" v-model.number="receiptWidth" :disabled="!activeMedia" type="range" min="35" max="80" step="1" class="w-full disabled:opacity-50" /></div><label class="flex items-center gap-2"><Checkbox v-model:checked="showChange" /> Show change due to customer during payment</label><p class="pl-6 text-xs text-muted-foreground">Shows the cash change only when the amount tendered is higher than the amount due.</p><div class="flex items-center justify-between gap-3"><label class="flex items-center gap-2"><Checkbox v-model:checked="paymentScreen" /> Show payment success screen</label><Button size="sm" variant="outline" :disabled="!paymentScreen" @click="editingPayment = !editingPayment">{{ editingPayment ? 'Close payment screen editor' : 'Customize payment screen' }}</Button></div></div>
			<div v-if="editingPayment" class="rounded-lg border border-border p-3 space-y-3"><p class="font-medium">Payment Success Screen</p><div class="flex gap-2"><Button size="sm" :variant="payment.mode === 'template' ? 'default' : 'outline'" @click="payment.mode = 'template'">Designed template</Button><Button size="sm" :variant="payment.mode === 'html' ? 'default' : 'outline'" @click="payment.mode = 'html'">Custom HTML</Button></div><template v-if="payment.mode === 'template'"><label>Title<Input v-model="payment.title" placeholder="Thank You!" /></label><label>Message<Input v-model="payment.message" placeholder="Thank you for shopping with Lozira Collection." /></label><label>Footer<Input v-model="payment.footer" placeholder="Visit us again ❤️" /></label><div class="flex flex-wrap items-center gap-3"><img v-if="payment.image" :src="payment.image" class="logo-preview" alt="Payment logo preview" /><input id="payment-display-logo" class="sr-only" type="file" accept="image/*" @change="uploadPaymentLogo" /><label for="payment-display-logo" class="file-button">Upload payment logo</label><Button v-if="payment.image" size="sm" variant="outline" @click="payment.image = ''">Remove</Button></div><p v-if="payment.image" class="text-xs" :class="paymentLogoStatusClass">{{ fileName(payment.image) }} · {{ paymentLogoStatus }}</p><label>Promo message <Input v-model="payment.promo" placeholder="Join our membership for exclusive rewards" /></label></template><label v-else>Payment screen HTML<textarea v-model="payment.html" rows="8" placeholder="&lt;h1&gt;Thank You!&lt;/h1&gt;" @keydown.stop /></label></div>
			<div class="space-y-2"><label class="font-medium" for="customer-display-delay">Show advertisement after payment (seconds)</label><Input id="customer-display-delay" v-model.number="returnDelay" type="number" min="5" max="60" class="w-28" /></div>
			<div class="space-y-2"><label class="font-medium" for="customer-display-language">Language</label><select id="customer-display-language" v-model="language" class="select"><option value="en">English</option><option value="ms">Bahasa Melayu</option></select></div>
		</div><AdvertisementManager v-else />
		<DialogFooter><Button variant="outline" @click="$emit('close')">Close</Button></DialogFooter>
	</DialogContent></Dialog>
</template>
<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from "vue"; import { Monitor } from "lucide-vue-next"; import { Button } from "@/components/ui/button"; import { Checkbox } from "@/components/ui/checkbox"; import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog"; import { Input } from "@/components/ui/input"; import { toast } from "vue-sonner"; import { createCustomerDisplayChannel, getCustomerDisplaySessionId } from "@/services/customerDisplayChannel"; import { applyLocalCustomerDisplayConfiguration, CUSTOMER_DISPLAY_SAVED_SETUP_KEY, type CustomerDisplaySetup, checkCustomerDisplayMedia, createCustomerDisplayConfiguration, deleteCustomerDisplayConfiguration, listCustomerDisplayConfigurations, loadCustomerDisplayConfiguration, readLocalCustomerDisplayConfiguration, saveCustomerDisplayConfiguration } from "@/services/customerDisplayStorage"; import AdvertisementManager from "./AdvertisementManager.vue";
type PaymentContent = { mode: "template" | "html"; title: string; message: string; footer: string; image: string; promo: string; html: string }; const defaultPayment = (): PaymentContent => ({ mode: "template", title: "Thank You!", message: "Thank you for shopping with Lozira Collection.", footer: "Visit us again ❤️", image: "", promo: "", html: "<h1>Thank You!</h1><p>Thank you for shopping with us.</p>" }); function loadPayment(): PaymentContent { try { return { ...defaultPayment(), ...JSON.parse(localStorage.getItem("xpos.customerDisplay.paymentContent") || "{}") }; } catch { return defaultPayment(); } }
const props = defineProps<{ open: boolean }>(); defineEmits<{ close: [] }>(); const enabled = ref(localStorage.getItem("xpos.customerDisplay.enabled") !== "false"), sessionId = ref(getCustomerDisplaySessionId()), returnDelay = ref(Number(localStorage.getItem("xpos.customerDisplay.returnDelay") || 10)), connected = ref(false), tab = ref<"quick" | "content" | "settings">("quick"), activeMedia = ref(localStorage.getItem("xpos.customerDisplay.activeMedia") !== "false"), receiptWidth = ref(Math.max(35, Math.min(80, Number(localStorage.getItem("xpos.customerDisplay.receiptWidth") || 58)))), showChange = ref(localStorage.getItem("xpos.customerDisplay.showChange") !== "false"), paymentScreen = ref(localStorage.getItem("xpos.customerDisplay.paymentScreen") !== "false"), editingPayment = ref(false), payment = ref<PaymentContent>(loadPayment()), companyLogo = ref(localStorage.getItem("xpos.customerDisplay.companyLogo") || ""), language = ref<"en" | "ms">(localStorage.getItem("xpos.customerDisplay.language") === "ms" ? "ms" : "en"), savedSetups = ref<CustomerDisplaySetup[]>([]), selectedSetup = ref(""), setupName = ref(""), logoStatus = ref("Checking…"), logoStatusClass = ref("text-muted-foreground"), paymentLogoStatus = ref("Checking…"), paymentLogoStatusClass = ref("text-muted-foreground"); let channel: BroadcastChannel | null = null;
const storageLabel = ref("Saved locally for offline use. Restore to load the ERPNext copy."), pairingUrl = computed(() => `${window.location.origin}/xpos/customer-display?session=${encodeURIComponent(sessionId.value)}`), connectionLabel = computed(() => connected.value ? "Customer screen connected" : "Waiting for customer screen"), connectionClass = computed(() => connected.value ? "text-emerald-600" : "text-amber-600"), connectionHelp = computed(() => connected.value ? "Live cart updates are available on this terminal." : "Open the customer window from this dialog. It must use the same Chrome profile and terminal ID."); let saveTimer: number | undefined, connectionTimer: number | undefined, lastDisplayReady = 0;
function saveConfig() { const id = sessionId.value.trim() || getCustomerDisplaySessionId(); sessionId.value = id; returnDelay.value = Math.max(5, Math.min(60, Number(returnDelay.value) || 10)); const settings: Record<string, string> = { enabled: String(enabled.value), sessionId: id, returnDelay: String(returnDelay.value), activeMedia: String(activeMedia.value), receiptWidth: String(Math.max(35, Math.min(80, Number(receiptWidth.value) || 58))), showChange: String(showChange.value), paymentScreen: String(paymentScreen.value), paymentContent: JSON.stringify(payment.value), companyLogo: companyLogo.value, language: language.value }; Object.entries(settings).forEach(([key, value]) => localStorage.setItem(`xpos.customerDisplay.${key}`, value)); window.dispatchEvent(new CustomEvent("xpos:customer-display-config", { detail: { enabled: enabled.value, sessionId: id } })); window.dispatchEvent(new CustomEvent("xpos:customer-display-storage")); scheduleServerSave(); }
function scheduleServerSave() { if (selectedSetup.value !== sessionId.value) return; if (saveTimer) window.clearTimeout(saveTimer); saveTimer = window.setTimeout(() => { void saveServerConfig(); }, 700); }
async function saveServerConfig(): Promise<boolean> { try { const playlist = JSON.parse(localStorage.getItem("xpos.customerDisplay.playlist") || "[]"); await saveCustomerDisplayConfiguration(sessionId.value, readLocalCustomerDisplayConfiguration(Array.isArray(playlist) ? playlist : [])); storageLabel.value = "Saved in ERPNext. A local offline copy is also kept on this browser."; return true; } catch { storageLabel.value = "Saved locally only. Sign in as a System Manager to save the shared ERPNext copy."; return false; } }
function loadLocalConfig() { enabled.value = localStorage.getItem("xpos.customerDisplay.enabled") !== "false"; returnDelay.value = Number(localStorage.getItem("xpos.customerDisplay.returnDelay") || 10); activeMedia.value = localStorage.getItem("xpos.customerDisplay.activeMedia") !== "false"; receiptWidth.value = Math.max(35, Math.min(80, Number(localStorage.getItem("xpos.customerDisplay.receiptWidth") || 58))); showChange.value = localStorage.getItem("xpos.customerDisplay.showChange") !== "false"; paymentScreen.value = localStorage.getItem("xpos.customerDisplay.paymentScreen") !== "false"; payment.value = loadPayment(); companyLogo.value = localStorage.getItem("xpos.customerDisplay.companyLogo") || ""; language.value = localStorage.getItem("xpos.customerDisplay.language") === "ms" ? "ms" : "en"; }
function fileName(url: string) { try { return decodeURIComponent(new URL(url, window.location.origin).pathname.split("/").pop() || url); } catch { return url; } } async function refreshLogoStatus() { if (!companyLogo.value) { logoStatus.value = "No logo selected"; logoStatusClass.value = "text-muted-foreground"; return; } const status = (await checkCustomerDisplayMedia([companyLogo.value]).catch(() => []))[0]?.status; logoStatus.value = status === "available" ? "Available" : status === "missing" ? "Missing" : "URL unavailable"; logoStatusClass.value = status === "available" ? "text-emerald-600" : "text-destructive"; } async function refreshPaymentLogoStatus() { if (!payment.value.image) return; const status = (await checkCustomerDisplayMedia([payment.value.image]).catch(() => []))[0]?.status; paymentLogoStatus.value = status === "available" ? "Available" : status === "missing" ? "Missing" : "URL unavailable"; paymentLogoStatusClass.value = status === "available" ? "text-emerald-600" : "text-destructive"; }
async function restoreServerConfig() { const id = sessionId.value.trim(); if (!id) return toast.error("Enter the saved Terminal ID first"); try { const configuration = await loadCustomerDisplayConfiguration(id); if (!configuration) { if (await saveServerConfig()) storageLabel.value = "Current local settings were copied to ERPNext for this Terminal ID."; return; } applyLocalCustomerDisplayConfiguration(configuration); localStorage.setItem("xpos.customerDisplay.playlist", JSON.stringify(configuration.playlist || [])); sessionId.value = id; loadLocalConfig(); window.dispatchEvent(new CustomEvent("xpos:customer-display-storage")); storageLabel.value = "Restored from ERPNext. The local offline copy has been refreshed."; toast.success("Customer Display settings restored"); } catch { storageLabel.value = "Could not reach ERPNext; the local offline copy is still in use."; toast.error("Customer Display restore failed"); } }
async function refreshSavedSetups() { try { savedSetups.value = await listCustomerDisplayConfigurations(); if (savedSetups.value.some((setup) => setup.terminal_id === sessionId.value)) { selectedSetup.value = sessionId.value; localStorage.setItem(CUSTOMER_DISPLAY_SAVED_SETUP_KEY, sessionId.value); } } catch { storageLabel.value = "Could not load saved setups. The local offline copy is still available."; } }
function displaySetupName(id: string) { return /-[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(id) ? "Legacy unnamed setup" : id; }
async function saveAsSetup() { const name = setupName.value.trim(); if (!name) return toast.error("Enter a name for this display setup"); sessionId.value = name; saveConfig(); try { const playlist = JSON.parse(localStorage.getItem("xpos.customerDisplay.playlist") || "[]"); await createCustomerDisplayConfiguration(name, readLocalCustomerDisplayConfiguration(Array.isArray(playlist) ? playlist : [])); selectedSetup.value = name; localStorage.setItem(CUSTOMER_DISPLAY_SAVED_SETUP_KEY, name); setupName.value = ""; await refreshSavedSetups(); storageLabel.value = "Saved in ERPNext. A local offline copy is also kept on this browser."; toast.success("Display setup saved"); } catch { toast.error("This setup name is already used or could not be saved. Choose another name."); } }
async function updateSelectedSetup() { if (!selectedSetup.value) return toast.error("Select a saved display setup first"); sessionId.value = selectedSetup.value; saveConfig(); if (await saveServerConfig()) { await refreshSavedSetups(); toast.success("Display setup updated"); } }
async function restoreSelectedSetup() { if (!selectedSetup.value) return; sessionId.value = selectedSetup.value; await restoreServerConfig(); localStorage.setItem(CUSTOMER_DISPLAY_SAVED_SETUP_KEY, sessionId.value); monitorConnection(); }
async function deleteSelectedSetup() { const name = selectedSetup.value; if (!name || !window.confirm(`Delete saved display setup “${displaySetupName(name)}”? Uploaded logo and media files will remain on the server.`)) return; try { await deleteCustomerDisplayConfiguration(name); selectedSetup.value = ""; setupName.value = ""; localStorage.removeItem(CUSTOMER_DISPLAY_SAVED_SETUP_KEY); await refreshSavedSetups(); storageLabel.value = "Saved setup deleted. The current local display remains open until you select or save another setup."; toast.success("Display setup deleted"); } catch { toast.error("Could not delete display setup"); } }
async function uploadImage(event: Event, target: "company" | "payment") { const file = (event.target as HTMLInputElement).files?.[0]; if (!file) return; try { const form = new FormData(); form.append("file", file); form.append("is_private", "0"); const csrf = window.xpos?.csrf_token || (document.querySelector('meta[name="csrf-token"]') as HTMLMetaElement | null)?.content || ""; const response = await fetch("/api/method/upload_file", { method: "POST", body: form, credentials: "same-origin", headers: csrf ? { "X-Frappe-CSRF-Token": csrf } : {} }); const data = await response.json(); if (!response.ok || !data.message?.file_url) throw new Error(); if (target === "company") companyLogo.value = data.message.file_url; else payment.value.image = data.message.file_url; toast.success("Logo uploaded"); } catch { toast.error("Logo upload failed. Check Frappe File permission."); } }
function uploadLogo(event: Event) { return uploadImage(event, "company"); } function uploadPaymentLogo(event: Event) { return uploadImage(event, "payment"); }
function monitorConnection() { channel?.close(); if (connectionTimer) window.clearInterval(connectionTimer); connected.value = false; lastDisplayReady = 0; channel = createCustomerDisplayChannel(sessionId.value); if (!channel) return; channel.onmessage = (event: MessageEvent<{ type?: string }>) => { if (event.data?.type === "display-ready") { lastDisplayReady = Date.now(); connected.value = true; } if (event.data?.type === "display-closed") connected.value = false; }; const ping = () => { if (lastDisplayReady && Date.now() - lastDisplayReady > 7000) connected.value = false; channel?.postMessage({ type: "display-ping" }); }; ping(); connectionTimer = window.setInterval(ping, 3000); }
async function copyPairingUrl() { saveConfig(); try { await navigator.clipboard.writeText(pairingUrl.value); toast.success("Pairing link copied"); } catch { toast.error("Could not copy the pairing link"); } }
async function openCustomerDisplay() { saveConfig(); const popup = window.open(pairingUrl.value, "xpos-customer-display", "popup=yes,width=1024,height=768"); if (!popup) return toast.error("Popup was blocked. Allow popups for this site, then try again."); popup.focus(); monitorConnection(); }
watch([enabled, returnDelay, activeMedia, receiptWidth, showChange, paymentScreen, payment, companyLogo, language], saveConfig, { deep: true }); watch(companyLogo, () => { void refreshLogoStatus(); }); watch(() => payment.value.image, () => { void refreshPaymentLogoStatus(); }); watch(() => props.open, (isOpen) => { if (isOpen) { monitorConnection(); void refreshSavedSetups(); void refreshLogoStatus(); void refreshPaymentLogoStatus(); } else { channel?.close(); if (connectionTimer) window.clearInterval(connectionTimer); } }); onBeforeUnmount(() => { channel?.close(); if (saveTimer) window.clearTimeout(saveTimer); if (connectionTimer) window.clearInterval(connectionTimer); });
</script>
<style scoped>.select{display:flex;height:2.25rem;width:100%;border:1px solid hsl(var(--input));border-radius:.375rem;background:transparent;padding:.25rem .75rem;font-size:.875rem}textarea{width:100%;border:1px solid hsl(var(--input));border-radius:.375rem;background:transparent;padding:.5rem;font:inherit}.file-button{display:inline-flex;cursor:pointer;border:1px solid hsl(var(--border));border-radius:.375rem;padding:.45rem .7rem;background:hsl(var(--secondary));font-weight:600}.logo-preview{max-height:2.5rem;max-width:8rem;object-fit:contain}</style>
